    """Return whether an element is the majority element in the given sorted array."""
    # Find the first occurrence of the element
    left_index = 0
    right_index = length - 1

    while left_index <= right_index:
        mid_index = (left_index + right_index) // 2
        if arr[mid_index] < element:
            left_index = mid_index + 1
        elif arr[mid_index] > element:
            right_index = mid_index - 1
        else:
            left_index = mid_index
            break

    # Find the last occurrence of the element
    left_index_last = 0
    right_index_last = length - 1

    while left_index_last <= right_index_last:
        mid_index = (left_index_last + right_index_last) // 2
        if arr[mid_index] < element:
            left_index_last = mid_index + 1
        elif arr[mid_index] > element:
            right_index_last = mid_index - 1
        else:
            right_index_last = mid_index
            break

    # Calculate the length of the subarray where the element is found
    if left_index_last <= right_index_last and left_index <= right_index:
        return (right_index_last - left_index_last + 1) > length // 2
    else:
        return False
