def sort_counter(d, with_duplicates=False):
    """Return a sorted list of tuples (key, value) from a dictionary d, with or without handling duplicates."""
    from collections import Counter
    if with_duplicates:
        # Creating a Counter object for a dictionary with possible duplicates
        counter = Counter()
        for key, value in d.items():
            counter[key] += value
        # Using most_common method to handle duplicates
        return counter.most_common()
    else:
        return sorted(d.items(), key=lambda x: x[1], reverse=True)

# Example usage
